!function(){var e=window.SureCartAffiliatesConfig||{};if(e.endpoint){var i=new URLSearchParams(window.location.search).get("aff");i&&fetch(e.endpoint,{method:"POST",keepalive:!0,headers:{"Content-Type":"application/json"},body:JSON.stringify({affiliation_code:i,url:window.location.href,referrer:document.referrer})}).catch((function(e){console.warn("SureCart Affiliates: Tracking Failed -",e)}))}}();